def convertir_les_decisions(apps, schema_editor):
    """Une décision est « maintenue » si elle reprend les nombres de l'étape précédente, sinon « modifiée »."""
    Validation = apps.get_model("personnel", "ValidationBesoin")
    for validation in Validation.objects.select_related("fiche"):
        if validation.etape == "conference":
            base = (validation.fiche.fonctionnaires, validation.fiche.contractuels)
        else:
            conference = Validation.objects.filter(fiche=validation.fiche, etape="conference").first()
